-- Tiny factor_series for the P66 EY provider (schema as ../idx-method/store/data/stockbiter.db,
-- read-only 2026-11-07): daily pe and mktcap, a loss maker, a zero PE, a delisted name echoed on
-- the pull date (2026-11-03 here) and a name gone quiet before the window.
CREATE TABLE factor_series (
    freq   TEXT NOT NULL,
    symbol TEXT NOT NULL,
    item   TEXT NOT NULL,
    date   TEXT NOT NULL,
    value,
    PRIMARY KEY (freq, symbol, item, date)
);
